mapper.select:
INSERT INTO raw_observation (
provider_id, endpoint, request_key, received_at, provider_observed_at, response_status, payload, expires_at
) VALUES(
#{providerId}, #{endpoint}, #{requestKey}, #{receivedAt}, #{providerObservedAt}, #{responseStatus}, CAST(#{payload} AS JSONB), #{expiresAt}
) RETURNING id

mapper.delete:
DELETE FROM raw_observation
WHERE id IN (
SELECT id
FROM raw_observation
WHERE expires_at IS NOT NULL
AND expires_at  <=  #{expiresAtOrBefore}
ORDER BY expires_at ASC, id ASC
LIMIT #{limit}
)

mapper.select:
SELECT 
FROM raw_observation
WHERE provider_id = #{providerId}
AND endpoint = #{endpoint}
AND request_key = #{requestKey}
ORDER By received_at DESC, id DESC
LIMIT 1

SELECT 
FROM raw_observation
WHERE provider_id = #{providerId}
AND endpoint = #{endpoint}
AND request_key = #{requestKey}
AND response_status  >=  200
AND response_status  <  300
AND payload IS NOT NULL
AND expires_at  >  #{asOf}
ORDER BY received_at DESC, id DESC
LIMIT 1
